"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('00-state-lab'))return;const {svg,fmt}=L;
function render(){const v=L.range('velocity'),t=L.range('time'),x=v*t,g=L.$('drawing'),root=g.ownerSVGElement,W=Math.max(240,Math.min(660,root.parentElement.clientWidth)),X=z=>W/2+(W-64)*z/4;root.setAttribute('viewBox','0 0 '+W+' 345');g.replaceChildren();g.append(svg('text',{x:22,y:28,class:'svg-label'},'右方為正 →'),svg('text',{x:W-22,y:28,'text-anchor':'end',class:'svg-small'},'經過 '+fmt(t)+' s'));
[127,270].forEach((y,i)=>{g.append(svg('text',{x:22,y:y-56,class:'svg-label'},i?'B 車：'+fmt(x)+' m':'A 車：0 m'),svg('line',{x1:18,y1:y+18,x2:W-18,y2:y+18,class:'axis'}));for(let z=-2;z<=2;z++){g.append(svg('line',{x1:X(z),y1:y+13,x2:X(z),y2:y+24,class:'axis'}),svg('text',{x:X(z),y:y+45,'text-anchor':'middle',class:'svg-small'},z+' m'));}const cx=X(i?x:0),color=i?'#345cdf':'#cf604b';g.append(svg('rect',{x:cx-19,y:y-21,width:38,height:25,rx:7,fill:color}),svg('circle',{cx:cx-11,cy:y+9,r:6,fill:'#172a45'}),svg('circle',{cx:cx+11,cy:y+9,r:6,fill:'#172a45'}));if(i&&v!==0){const start=cx,end=Math.max(14,Math.min(W-14,cx+v*32));g.append(svg('path',{d:`M${start} ${y-31}H${end}l${-Math.sign(v)*7} -5m${Math.sign(v)*7} 5l${-Math.sign(v)*7} 5`,stroke:'#345cdf','stroke-width':2,fill:'none'}));}});
L.text('result-primary',fmt(x)+' m');L.text('result-secondary',fmt(v)+' m/s');L.text('feedback',t===0?(v===0?'時間還沒往前：兩車都在 0 m，速度也都是 0 m/s。在這個無外力模型中，此後兩車都會維持在原點。':'時間還沒往前：兩車都在 0 m；但 B 車的速度卡是 '+fmt(v)+' m/s，下一個正時間兩車的位置就會不同。'):v===0?'B 車速度是 0 m/s。經過 '+fmt(t)+' s，它和 A 車都仍在原點。':'B 車每秒向'+(v>0?'右':'左')+'走 '+fmt(Math.abs(v))+' m；經過 '+fmt(t)+' s，位置 = 0 + ('+fmt(v)+') × '+fmt(t)+' = '+fmt(x)+' m。速度卡沒有改變，因為模型中沒有合外力。');}
L.init(['velocity','time'],render);window.addEventListener('resize',render);})();
